14	/// Determine if a regex expression contains a literal uppercase character.
15	fn hir_has_uppercase_char(hir: &Hir) -> bool {
16	    use regex_syntax::hir::*;
17	
18	    match hir.kind() {
19	        HirKind::Literal(Literal(bytes)) => match std::str::from_utf8(bytes) {
20	            Ok(s) => s.chars().any(|c| c.is_uppercase()),
21	            Err(_) => bytes.iter().any(|b| char::from(*b).is_uppercase()),
22	        },
23	        HirKind::Class(Class::Unicode(ranges)) => ranges
24	            .iter()
25	            .any(|r| r.start().is_uppercase() || r.end().is_uppercase()),
26	        HirKind::Class(Class::Bytes(ranges)) => ranges
27	            .iter()
28	            .any(|r| char::from(r.start()).is_uppercase() || char::from(r.end()).is_uppercase()),
29	        HirKind::Capture(Capture { sub, .. }) | HirKind::Repetition(Repetition { sub, .. }) => {
30	            hir_has_uppercase_char(sub)
31	        }
32	        HirKind::Concat(hirs) | HirKind::Alternation(hirs) => {
33	            hirs.iter().any(hir_has_uppercase_char)
34	        }
35	        _ => false,
36	    }
37	}
