50	fn hir_matches_strings_with_leading_dot(hir: &Hir) -> bool {
51	    use regex_syntax::hir::*;
52	
53	    // Note: this only really detects the simplest case where a regex starts with
54	    // "^\\.", i.e. a start text anchor and a literal dot character. There are a lot
55	    // of other patterns that ONLY match hidden files, e.g. ^(\\.foo|\\.bar) which are
56	    // not (yet) detected by this algorithm.
57	    match hir.kind() {
58	        HirKind::Concat(hirs) => {
59	            let mut hirs = hirs.iter();
60	            if let Some(hir) = hirs.next() {
61	                if hir.kind() != &HirKind::Look(Look::Start) {
62	                    return false;
63	                }
64	            } else {
65	                return false;
66	            }
