68	            if let Some(hir) = hirs.next() {
69	                match hir.kind() {
70	                    HirKind::Literal(Literal(bytes)) => bytes.starts_with(b"."),
71	                    _ => false,
72	                }
73	            } else {
74	                false
75	            }
76	        }
